package com.soumya.walletwise.finance;
import com.fasterxml.jackson.databind.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import javax.crypto.*;import javax.crypto.spec.*;import java.nio.charset.*;import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.*;import org.springframework.stereotype.*;
@Component public class JwtFilter implements Filter{private final String secret;private final ObjectMapper json=new ObjectMapper();public JwtFilter(@Value("${walletwise.jwt.secret}")String s){secret=s;}public void doFilter(ServletRequest q,ServletResponse r,FilterChain c)throws java.io.IOException,ServletException{HttpServletRequest h=(HttpServletRequest)q;if(h.getRequestURI().endsWith("/health")){c.doFilter(q,r);return;}try{String a=h.getHeader("Authorization");if(a==null||!a.startsWith("Bearer "))throw new Exception();String[]p=a.substring(7).split("\\.");Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String sig=Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal((p[0]+"."+p[1]).getBytes(StandardCharsets.UTF_8)));Map claims=json.readValue(Base64.getUrlDecoder().decode(p[1]),Map.class);if(p.length!=3||!sig.equals(p[2])||((Number)claims.get("exp")).longValue()<Instant.now().getEpochSecond())throw new Exception();h.setAttribute("userId",claims.get("sub"));h.setAttribute("role",claims.get("role"));c.doFilter(q,r);}catch(Exception e){((HttpServletResponse)r).sendError(401,"Unauthorized");}}}
